                                 </label>
                                 <div className="space-y-3">
                                     <div>
                                         <label className={`block text-xs font-medium mb-1 ${theme === 'dark' ? 'text-slate-400' : 'text-slate-600'}`}>Phone Number</label>
                                         <PhoneInput theme={theme} value={clientInfo.phone} onChange={handleClientPhoneChange} />
                                     </div>
                                     <div>
                                         <label className={`block text-xs font-medium mb-1 ${theme === 'dark' ? 'text-slate-400' : 'text-slate-600'}`}>Client Name</label>
                                         <div className="relative">
                                             <input 
                                                type="text" 
                                                placeholder="Name"
                                                value={clientInfo.name}
                                                onChange={(e) => setClientInfo({...clientInfo, name: e.target.value})}
                                                className={inputClass}
                                                readOnly={isExistingClient} // Optionally lock name if found
                                             />
                                             {isExistingClient && (
                                                 <div className="absolute inset-y-0 right-0 flex items-center pr-3 pointer-events-none">
                                                     <Icon name="check-circle" className="h-4 w-4 text-green-500" />
                                                 </div>
                                             )}
                                         </div>
                                         {isExistingClient && <p className="text-xs text-green-500 mt-1">Client found</p>}
                                     </div>
                                 </div>
                             </div>
                        )}

                        {/* Client Selection (Required for Debt/Wallet) */}
                        {(paymentMethod === 'Debt' || paymentMethod === 'Client Wallet') && selectedShop?.settings.enableWallets && (
                            <div className={`rounded-lg border shadow-sm p-4 animate-fade-in-down ${theme === 'dark' ? 'bg-slate-900 border-slate-700' : 'bg-white border-slate-200'}`}>
                                <label className={`block text-xs font-bold mb-2 uppercase tracking-wide text-red-500`}>
                                    Registered Client (Required)
                                </label>
                                <select 
                                    value={selectedClientId} 
                                    onChange={(e) => setSelectedClientId(e.target.value)}
                                    className={inputClass}
                                >
                                    <option value="">Select Registered Client</option>
                                    {clients.filter(c => c.status === 'Active').map(client => (
                                        <option key={client.id} value={client.id}>{client.name}</option>
                                    ))}
                                </select>

                                {paymentMethod === 'Client Wallet' && (
                                    <div className="mt-3">
                                        <label className={`block text-xs font-medium mb-1 ${theme === 'dark' ? 'text-slate-400' : 'text-slate-600'}`}>
                                            Transaction Reference
                                        </label>
                                        <input 
                                            type="text" 
                                            value={paymentReference}
                                            onChange={(e) => setPaymentReference(e.target.value)}
                                            className={inputClass} 
                                            placeholder="Enter reference..."
                                        />
                                    </div>
                                )}
                            </div>
                        )}

                        {/* Action Buttons */}
                        <div className="grid grid-cols-2 gap-3">
                             <button 
                                onClick={handleClearCart}
                                disabled={cart.length === 0}
                                className={`py-3 rounded-md text-sm font-bold border transition-colors ${theme === 'dark' ? 'border-slate-600 text-slate-300 hover:bg-slate-800 disabled:opacity-50 disabled:cursor-not-allowed' : 'bg-white border-slate-300 text-slate-700 hover:bg-slate-100 disabled:opacity-50 disabled:cursor-not-allowed'}`}
                            >
                                Cancel
                            </button>
                            <button 
                                onClick={handleConfirmPurchase}
                                disabled={cart.length === 0}
                                className="py-3 rounded-md text-sm font-bold bg-black text-yellow-500 hover:bg-slate-900 transition-colors shadow-lg disabled:opacity-50 disabled:cursor-not-allowed"
                            >
                                Confirm
                            </button>
                        </div>

                        {selectedShop?.settings.allowHoldTransaction && (
                             <button 
                                onClick={handleHoldTransaction}
                                disabled={cart.length === 0}
                                className={`w-full py-3 rounded-md text-sm font-bold border border-dashed transition-colors ${theme === 'dark' ? 'border-slate-600 text-slate-400 hover:bg-slate-800 disabled:opacity-50 disabled:cursor-not-allowed' : 'border-slate-300 text-slate-600 hover:bg-slate-50 disabled:opacity-50 disabled:cursor-not-allowed'}`}
                            >
                                Hold Transaction
                            </button>
                        )}

                    </div>
                </div>
            </div>
        </>
    );
};

