      <Icon name={icon} className="h-5 w-5 flex-shrink-0" />
      <span className={`whitespace-nowrap transition-all duration-200 overflow-hidden ${isCollapsed ? 'w-0 ml-0 opacity-0' : 'w-auto ml-3 opacity-100'}`}>{label}</span>
