import React, { useState, useMemo, useEffect } from 'react';
import { Theme, Shop, StockItem, User } from '../types';
import Icon from './Icon';
import { mockShops, mockStockListings } from '../data';

interface CustomerMakeOrderPageProps {
    theme: Theme;
    currentUser: User;
}

interface CartItem extends StockItem {
    cartQuantity: number;
}

const MAX_DISTANCE_KM = 5; // Increased default radius for better demo visibility
const USER_LOCATION = { lat: 0.3476, lng: 32.5825 }; // Mock location (Kampala)

const calculateDistance = (lat1: number, lon1: number, lat2: number, lon2: number) => {
    const R = 6371; // Radius of the earth in km
    const dLat = deg2rad(lat2 - lat1);
    const dLon = deg2rad(lon2 - lon1);
    const a =
        Math.sin(dLat / 2) * Math.sin(dLat / 2) +
        Math.cos(deg2rad(lat1)) * Math.cos(deg2rad(lat2)) *
        Math.sin(dLon / 2) * Math.sin(dLon / 2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    const d = R * c; // Distance in km
    return d;
};

const deg2rad = (deg: number) => {
    return deg * (Math.PI / 180);
};

const PaymentModal: React.FC<{
    isOpen: boolean;
    onClose: () => void;
    amount: number;
    onConfirm: (method: string) => void;
    theme: Theme;
}> = ({ isOpen, onClose, amount, onConfirm, theme }) => {
    const [method, setMethod] = useState('Mobile Money');
    if (!isOpen) return null;

    return (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/60 p-4">
