                </div>
                <div className="p-6 space-y-4">
                    <label className={`block text-sm font-medium ${theme === 'dark' ? 'text-slate-300' : 'text-slate-700'}`}>Select Payment Method</label>
                    <div className="space-y-2">
                        {['Mobile Money', 'Card', 'Wallet', 'Cash on Delivery'].map((m) => (
                            <button
                                key={m}
                                onClick={() => setMethod(m)}
                                className={`w-full flex items-center justify-between p-3 rounded-lg border ${method === m ? 'border-yellow-500 ring-1 ring-yellow-500' : (theme === 'dark' ? 'border-slate-700 hover:bg-slate-800' : 'border-slate-200 hover:bg-slate-50')}`}
                            >
                                <span className={theme === 'dark' ? 'text-slate-200' : 'text-slate-800'}>{m}</span>
                                {method === m && <Icon name="check-circle" className="h-5 w-5 text-yellow-500" />}
                            </button>
                        ))}
                    </div>
                </div>
                <div className={`p-6 border-t flex justify-end gap-3 ${theme === 'dark' ? 'border-slate-700 bg-slate-800/50' : 'border-slate-200 bg-slate-50'}`}>
                    <button onClick={onClose} className={`px-4 py-2 rounded text-sm font-medium ${theme === 'dark' ? 'bg-slate-800 text-slate-300' : 'bg-white border text-slate-700'}`}>Cancel</button>
                    <button onClick={() => onConfirm(method)} className="px-4 py-2 rounded text-sm font-bold bg-yellow-500 text-slate-900 hover:bg-yellow-600">Pay & Order</button>
                </div>
            </div>
        </div>
    );
};

const CustomerMakeOrderPage: React.FC<CustomerMakeOrderPageProps> = ({ theme, currentUser }) => {
    const [selectedShopId, setSelectedShopId] = useState<string>('');
    const [productSearch, setProductSearch] = useState('');
    const [cart, setCart] = useState<CartItem[]>([]);
    const [isPaymentOpen, setIsPaymentOpen] = useState(false);

    // Sort shops by distance
    const nearbyShops = useMemo(() => {
        return mockShops
            .map(shop => ({
                ...shop,
                distance: calculateDistance(USER_LOCATION.lat, USER_LOCATION.lng, shop.location.lat, shop.location.lng)
            }))
            .filter(shop => shop.status === 'Active')
            .sort((a, b) => a.distance - b.distance);
    }, []);

    // Set default shop
    useEffect(() => {
        if (nearbyShops.length > 0 && !selectedShopId) {
            setSelectedShopId(nearbyShops[0].id.toString());
        }
    }, [nearbyShops, selectedShopId]);

    const selectedShop = useMemo(() => nearbyShops.find(s => s.id.toString() === selectedShopId), [selectedShopId, nearbyShops]);

    const shopProducts = useMemo(() => {
        if (!selectedShopId) return [];
        return mockStockListings.filter(item => 
            item.shopId.toString() === selectedShopId && 
            (item.productName.toLowerCase().includes(productSearch.toLowerCase()) || item.category.toLowerCase().includes(productSearch.toLowerCase()))
        );
    }, [selectedShopId, productSearch]);

    const handleAddToCart = (item: StockItem) => {
        if (item.quantity <= 0) return;
        setCart(prev => {
            const existing = prev.find(i => i.id === item.id);
            if (existing) {
                return prev.map(i => i.id === item.id ? { ...i, cartQuantity: i.cartQuantity + 1 } : i);
            }
            return [...prev, { ...item, cartQuantity: 1 }];
        });
    };

    const handleRemoveFromCart = (itemId: number) => {
        setCart(prev => prev.filter(i => i.id !== itemId));
    };

    const handleUpdateQty = (itemId: number, delta: number) => {
        setCart(prev => prev.map(i => {
            if (i.id === itemId) {
                const newQty = i.cartQuantity + delta;
                return newQty > 0 && newQty <= i.quantity ? { ...i, cartQuantity: newQty } : i;
            }
            return i;
        }));
    };

    const cartTotal = cart.reduce((sum, item) => sum + (item.unitPrice * item.cartQuantity), 0);

    const handlePlaceOrder = (method: string) => {
        alert(`Order placed successfully at ${selectedShop?.name} via ${method}!\nTotal: UGX ${cartTotal.toLocaleString()}`);
        setIsPaymentOpen(false);
        setCart([]);
