            {/* Header / Shop Selection */}
            <div className={`flex-shrink-0 p-4 mb-4 rounded-lg shadow-sm border ${theme === 'dark' ? 'bg-slate-900 border-slate-700 text-slate-100' : 'bg-white border-slate-200 text-slate-900'}`}>
