                     <div>
                        <h2 className="text-xl font-bold">Make an Order</h2>
                        <p className={`text-sm ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>Select a nearby shop and add items to your cart.</p>
                     </div>
                     <div className="flex flex-col sm:flex-row gap-4 w-full md:w-auto">
                        <div className="w-full sm:w-64">
                             <label className={`block text-xs font-semibold uppercase tracking-wider mb-1 ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>Select Shop</label>
                             <div className="relative">
                                <Icon name="shop-mgt" className={`absolute left-3 top-2.5 h-4 w-4 ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`} />
                                <select 
                                    value={selectedShopId} 
                                    onChange={(e) => { setSelectedShopId(e.target.value); setCart([]); }}
                                    className={`${inputClass} pl-9 pr-8 py-2 text-sm`}
                                >
                                    {nearbyShops.map(shop => (
                                        <option key={shop.id} value={shop.id}>
                                            {shop.name} ({shop.distance.toFixed(1)} km)
                                        </option>
                                    ))}
                                </select>
                                <Icon name="chevron-down" className={`absolute right-3 top-3 h-4 w-4 pointer-events-none ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`} />
                             </div>
                        </div>
                        <div className="w-full sm:w-64">
                            <label className={`block text-xs font-semibold uppercase tracking-wider mb-1 ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>Search Items</label>
                            <div className="relative">
                                <Icon name="search" className={`absolute left-3 top-2.5 h-4 w-4 ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`} />
                                <input 
                                    type="text" 
                                    placeholder="Find products..." 
                                    value={productSearch}
                                    onChange={(e) => setProductSearch(e.target.value)}
                                    className={`${inputClass} pl-9 py-2 text-sm`}
                                />
                            </div>
                        </div>
                     </div>
                </div>
            </div>

            {/* Main Content Area: Products Grid */}
            <div className="flex-grow overflow-y-auto mb-4 pb-20 custom-scrollbar">
                {shopProducts.length > 0 ? (
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                        {shopProducts.map(item => {
                            const inCart = cart.find(c => c.id === item.id);
                            return (
                                <div key={item.id} className={`p-4 rounded-lg border flex flex-col justify-between transition-all hover:shadow-md ${theme === 'dark' ? 'bg-slate-900 border-slate-700 hover:border-slate-600' : 'bg-white border-slate-200 hover:border-slate-300'}`}>
                                    <div>
                                        <div className="flex justify-between items-start mb-2">
                                            <h4 className={`font-semibold text-sm line-clamp-2 ${theme === 'dark' ? 'text-slate-200' : 'text-slate-800'}`}>{item.productName}</h4>
                                            <span className={`text-[10px] px-2 py-0.5 rounded-full ${item.quantity < 10 ? 'bg-red-100 text-red-800' : 'bg-green-100 text-green-800'}`}>
                                                {item.quantity} left
                                            </span>
                                        </div>
                                        <p className={`text-xs mb-3 ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>{item.category}</p>
                                    </div>
                                    <div className="flex items-center justify-between mt-2 pt-3 border-t border-dashed border-gray-200 dark:border-gray-700">
                                        <span className={`font-bold text-sm ${theme === 'dark' ? 'text-white' : 'text-black'}`}>{item.currency} {item.unitPrice.toLocaleString()}</span>
                                        {inCart ? (
                                            <div className="flex items-center gap-2">
                                                <button onClick={() => handleUpdateQty(item.id, -1)} className={`w-6 h-6 rounded flex items-center justify-center border ${theme === 'dark' ? 'border-slate-600 hover:bg-slate-700' : 'border-slate-300 hover:bg-slate-100'}`}>-</button>
                                                <span className={`text-sm w-4 text-center font-medium ${theme === 'dark' ? 'text-white' : 'text-black'}`}>{inCart.cartQuantity}</span>
                                                <button onClick={() => handleUpdateQty(item.id, 1)} className={`w-6 h-6 rounded flex items-center justify-center border ${theme === 'dark' ? 'border-slate-600 hover:bg-slate-700' : 'border-slate-300 hover:bg-slate-100'}`}>+</button>
                                            </div>
                                        ) : (
                                            <button 
                                                onClick={() => handleAddToCart(item)}
                                                disabled={item.quantity <= 0}
                                                className={`px-3 py-1.5 text-xs font-bold uppercase tracking-wider rounded transition-colors ${item.quantity <= 0 ? 'bg-slate-200 text-slate-400 cursor-not-allowed' : 'bg-yellow-500 text-slate-900 hover:bg-yellow-400'}`}
                                            >
                                                Add
                                            </button>
                                        )}
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                ) : (
                    <div className="flex flex-col items-center justify-center h-64 text-center">
                        <Icon name="search" className={`h-12 w-12 mb-2 ${theme === 'dark' ? 'text-slate-600' : 'text-slate-300'}`} />
                        <p className={`text-sm ${theme === 'dark' ? 'text-slate-500' : 'text-slate-400'}`}>No products found for this shop.</p>
                    </div>
                )}
            </div>

            {/* Bottom Cart Panel (Selected Items) */}
            <div className={`fixed bottom-0 left-0 right-0 md:absolute md:w-full z-20 border-t shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.1)] transition-transform duration-300 ${theme === 'dark' ? 'bg-slate-800 border-slate-700' : 'bg-white border-slate-200'} ${cart.length === 0 ? 'translate-y-full' : 'translate-y-0'}`}>
                <div className="max-w-7xl mx-auto p-4">
                    <div className="flex justify-between items-center mb-4">
                        <h3 className={`font-bold text-lg ${theme === 'dark' ? 'text-white' : 'text-slate-900'}`}>
                            Selected Items <span className="text-sm font-normal text-slate-500">({cart.length})</span>
                        </h3>
                        <button onClick={() => setCart([])} className="text-xs text-red-500 hover:underline">Clear All</button>
                    </div>

                    {/* Cart Items List - Horizontal Scroll on Mobile */}
                    <div className="flex gap-4 overflow-x-auto pb-4 custom-scrollbar">
                        {cart.map(item => (
                            <div key={item.id} className={`flex-shrink-0 w-64 p-3 rounded-lg border flex items-center justify-between group ${theme === 'dark' ? 'bg-slate-900 border-slate-700' : 'bg-slate-50 border-slate-200'}`}>
                                <div className="flex-1 min-w-0 mr-3">
                                    <p className={`text-sm font-medium truncate ${theme === 'dark' ? 'text-slate-200' : 'text-slate-800'}`}>{item.productName}</p>
                                    <p className={`text-xs ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>
                                        {item.cartQuantity} x {item.unitPrice.toLocaleString()}
                                    </p>
                                </div>
                                <button onClick={() => handleRemoveFromCart(item.id)} className="text-slate-400 hover:text-red-500 p-1">
                                    <Icon name="x-mark" className="h-4 w-4" />
                                </button>
                            </div>
                        ))}
                    </div>

                    <div className="flex flex-col sm:flex-row justify-between items-center gap-4 mt-2 pt-4 border-t border-dashed border-gray-300 dark:border-gray-600">
                        <div>
                            <p className={`text-sm ${theme === 'dark' ? 'text-slate-400' : 'text-slate-500'}`}>Total Amount</p>
                            <p className={`text-2xl font-bold ${theme === 'dark' ? 'text-white' : 'text-slate-900'}`}>UGX {cartTotal.toLocaleString()}</p>
                        </div>
                        <button 
                            onClick={() => setIsPaymentOpen(true)}
                            className="w-full sm:w-auto px-8 py-3 bg-black text-yellow-500 font-bold rounded-lg hover:bg-slate-900 transition-colors shadow-lg"
                        >
                            Proceed to Checkout
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default CustomerMakeOrderPage;
